                let! props = Wire.closed [ "kind"; "event" ] path props
                let! () = Wire.required "kind" (Wire.literalString "Event") path props
                let! f_event = Wire.required "event" decodeSemanticEvent path props
                return BrowserToEngineMessage.Event(f_event)
            | "EffectResult" ->
                let! props = Wire.properties path element
                let! props = Wire.closed [ "kind"; "result" ] path props
                let! () = Wire.required "kind" (Wire.literalString "EffectResult") path props
                let! f_result = Wire.required "result" decodeEffectResult path props
                return BrowserToEngineMessage.EffectResult(f_result)
            | "LocationChanged" ->
                let! props = Wire.properties path element
                let! props = Wire.closed [ "kind"; "location" ] path props
                let! () = Wire.required "kind" (Wire.literalString "LocationChanged") path props
                let! f_location = Wire.required "location" decodeBrowserLocation path props
                return BrowserToEngineMessage.LocationChanged(f_location)
            | "CapabilityFact" ->
                let! props = Wire.properties path element
                let! props = Wire.closed [ "kind"; "capability"; "version"; "fact" ] path props
                let! () = Wire.required "kind" (Wire.literalString "CapabilityFact") path props
                let! f_capability = Wire.required "capability" decodeCapabilityId path props
                let! f_version = Wire.required "version" Wire.int path props
                let! f_fact = Wire.required "fact" Wire.json path props
                return BrowserToEngineMessage.CapabilityFact(f_capability, f_version, f_fact)
            | other -> return! Wire.unknownVariant (path + ".kind") other
        }

    and decodeViewPrimitive (path: string) (element: JsonElement) : Result<ViewPrimitive, DecodeError> =
        match Wire.kindOf element with
        | "string" -> Wire.string path element |> Result.map ViewPrimitive.Text
        | "number" -> Wire.number path element |> Result.map ViewPrimitive.Number
        | "boolean" -> Wire.boolean path element |> Result.map ViewPrimitive.Flag
        | _ -> Wire.mismatch "string | number | boolean" path element

    and decodeViewItem (path: string) (element: JsonElement) : Result<Map<string, ViewPrimitive>, DecodeError> =
        Wire.map decodeViewPrimitive path element

    and decodeViewValue (path: string) (element: JsonElement) : Result<ViewValue, DecodeError> =
        match Wire.kindOf element with
        | "string" -> Wire.string path element |> Result.map ViewValue.Text
        | "number" -> Wire.number path element |> Result.map ViewValue.Number
        | "boolean" -> Wire.boolean path element |> Result.map ViewValue.Flag
        | "array" -> (Wire.list decodeViewItem) path element |> Result.map ViewValue.Items
        | _ -> Wire.mismatch "string | number | boolean | array" path element

    and decodeViewState (path: string) (element: JsonElement) : Result<Map<string, ViewValue>, DecodeError> =
        Wire.map decodeViewValue path element

    and decodeHttpMethod (path: string) (element: JsonElement) : Result<HttpMethod, DecodeError> =
        Wire.enumeration [ "GET", HttpMethod.Get; "PUT", HttpMethod.Put; "POST", HttpMethod.Post; "PATCH", HttpMethod.Patch; "DELETE", HttpMethod.Delete ] path element

    and decodeHttpEffectRequest (path: string) (element: JsonElement) : Result<HttpEffectRequest, DecodeError> =
        Wire.decode {
            let! props = Wire.properties path element
            let! props = Wire.closed [ "kind"; "correlationId"; "method"; "url"; "headers"; "body"; "timeoutMs" ] path props
            let! () = Wire.required "kind" (Wire.literalString "Http") path props
            let! f_correlationId = Wire.required "correlationId" decodeCorrelationId path props
            let! f_method = Wire.required "method" decodeHttpMethod path props
            let! f_url = Wire.required "url" Wire.string path props
            let! f_headers = Wire.optional "headers" (Wire.map Wire.string) path props
            let! f_body = Wire.optional "body" Wire.string path props
            let! f_timeoutMs = Wire.required "timeoutMs" Wire.int path props
            return { CorrelationId = f_correlationId; Method = f_method; Url = f_url; Headers = f_headers; Body = f_body; TimeoutMs = f_timeoutMs }
        }

    and decodeStorageEffectRequest (path: string) (element: JsonElement) : Result<StorageEffectRequest, DecodeError> =
        Wire.decode {
            let! tag = Wire.tag "operation" path element
            match tag with
            | "get" ->
                let! props = Wire.properties path element
                let! props = Wire.closed [ "kind"; "operation"; "correlationId"; "key" ] path props
                let! () = Wire.required "kind" (Wire.literalString "Storage") path props
                let! () = Wire.required "operation" (Wire.literalString "get") path props
                let! f_correlationId = Wire.required "correlationId" decodeCorrelationId path props
                let! f_key = Wire.required "key" Wire.string path props
                return StorageEffectRequest.Get(f_correlationId, f_key)
            | "set" ->
                let! props = Wire.properties path element
                let! props = Wire.closed [ "kind"; "operation"; "correlationId"; "key"; "value" ] path props
                let! () = Wire.required "kind" (Wire.literalString "Storage") path props
                let! () = Wire.required "operation" (Wire.literalString "set") path props
                let! f_correlationId = Wire.required "correlationId" decodeCorrelationId path props
                let! f_key = Wire.required "key" Wire.string path props
                let! f_value = Wire.required "value" Wire.string path props
                return StorageEffectRequest.Set(f_correlationId, f_key, f_value)
            | "remove" ->
                let! props = Wire.properties path element
                let! props = Wire.closed [ "kind"; "operation"; "correlationId"; "key" ] path props
                let! () = Wire.required "kind" (Wire.literalString "Storage") path props
                let! () = Wire.required "operation" (Wire.literalString "remove") path props
                let! f_correlationId = Wire.required "correlationId" decodeCorrelationId path props
                let! f_key = Wire.required "key" Wire.string path props
                return StorageEffectRequest.Remove(f_correlationId, f_key)
            | other -> return! Wire.unknownVariant (path + ".operation") other
        }

    and decodeClipboardEffectRequest (path: string) (element: JsonElement) : Result<ClipboardEffectRequest, DecodeError> =
        Wire.decode {
            let! props = Wire.properties path element
            let! props = Wire.closed [ "kind"; "correlationId"; "operation"; "text" ] path props
            let! () = Wire.required "kind" (Wire.literalString "Clipboard") path props
            let! f_correlationId = Wire.required "correlationId" decodeCorrelationId path props
            let! () = Wire.required "operation" (Wire.literalString "writeText") path props
            let! f_text = Wire.required "text" Wire.string path props
            return { CorrelationId = f_correlationId; Text = f_text }
        }

    and decodeNavigationEffectRequest (path: string) (element: JsonElement) : Result<NavigationEffectRequest, DecodeError> =
        Wire.decode {
            let! tag = Wire.tag "operation" path element
            match tag with
            | "push" ->
                let! props = Wire.properties path element
                let! props = Wire.closed [ "kind"; "operation"; "correlationId"; "url" ] path props
                let! () = Wire.required "kind" (Wire.literalString "Navigation") path props
                let! () = Wire.required "operation" (Wire.literalString "push") path props
                let! f_correlationId = Wire.required "correlationId" decodeCorrelationId path props
                let! f_url = Wire.required "url" Wire.string path props
                return NavigationEffectRequest.Push(f_correlationId, f_url)
            | "replace" ->
                let! props = Wire.properties path element
                let! props = Wire.closed [ "kind"; "operation"; "correlationId"; "url" ] path props
                let! () = Wire.required "kind" (Wire.literalString "Navigation") path props
                let! () = Wire.required "operation" (Wire.literalString "replace") path props
                let! f_correlationId = Wire.required "correlationId" decodeCorrelationId path props
                let! f_url = Wire.required "url" Wire.string path props
                return NavigationEffectRequest.Replace(f_correlationId, f_url)
            | "back" ->
                let! props = Wire.properties path element
                let! props = Wire.closed [ "kind"; "operation"; "correlationId" ] path props
                let! () = Wire.required "kind" (Wire.literalString "Navigation") path props
                let! () = Wire.required "operation" (Wire.literalString "back") path props
                let! f_correlationId = Wire.required "correlationId" decodeCorrelationId path props
                return NavigationEffectRequest.Back(f_correlationId)
            | "forward" ->
                let! props = Wire.properties path element
                let! props = Wire.closed [ "kind"; "operation"; "correlationId" ] path props
                let! () = Wire.required "kind" (Wire.literalString "Navigation") path props
                let! () = Wire.required "operation" (Wire.literalString "forward") path props
                let! f_correlationId = Wire.required "correlationId" decodeCorrelationId path props
                return NavigationEffectRequest.Forward(f_correlationId)
            | other -> return! Wire.unknownVariant (path + ".operation") other
        }

    and decodeCapabilityEffectRequest (path: string) (element: JsonElement) : Result<CapabilityEffectRequest, DecodeError> =
        Wire.decode {
            let! props = Wire.properties path element
            let! props = Wire.closed [ "kind"; "correlationId"; "capability"; "version"; "request" ] path props
            let! () = Wire.required "kind" (Wire.literalString "Capability") path props
            let! f_correlationId = Wire.required "correlationId" decodeCorrelationId path props
            let! f_capability = Wire.required "capability" decodeCapabilityId path props
            let! f_version = Wire.required "version" Wire.int path props
            let! f_request = Wire.required "request" Wire.json path props
            return { CorrelationId = f_correlationId; Capability = f_capability; Version = f_version; Request = f_request }
        }

    and decodeEffectRequest (path: string) (element: JsonElement) : Result<EffectRequest, DecodeError> =
        Wire.decode {
            let! tag = Wire.tag "kind" path element
            match tag with
            | "Http" ->
                let! inner = decodeHttpEffectRequest path element
                return EffectRequest.Http inner
            | "Storage" ->
                let! inner = decodeStorageEffectRequest path element
                return EffectRequest.Storage inner
            | "Clipboard" ->
                let! inner = decodeClipboardEffectRequest path element
                return EffectRequest.Clipboard inner
            | "Navigation" ->
                let! inner = decodeNavigationEffectRequest path element
                return EffectRequest.Navigation inner
            | "Capability" ->
                let! inner = decodeCapabilityEffectRequest path element
                return EffectRequest.Capability inner
            | other -> return! Wire.unknownVariant (path + ".kind") other
        }

    and decodeEngineToBrowserMessage (path: string) (element: JsonElement) : Result<EngineToBrowserMessage, DecodeError> =
        Wire.decode {
            let! props = Wire.properties path element
            let! props = Wire.closed [ "view"; "effects"; "cancellations"; "handshake" ] path props
            let! f_view = Wire.required "view" decodeViewState path props
            let! f_effects = Wire.required "effects" (Wire.list decodeEffectRequest) path props
            let! f_cancellations = Wire.required "cancellations" (Wire.list decodeCorrelationId) path props
            let! f_handshake = Wire.optional "handshake" decodeEngineHandshake path props
            return { View = f_view; Effects = f_effects; Cancellations = f_cancellations; Handshake = f_handshake }
        }

    and encodeCorrelationId (value: CorrelationId) : JsonNode =
        let (CorrelationId inner) = value
        Wire.ofString inner

    and encodeCapability (value: Capability) : JsonNode =
        match value with
        | Capability.Http -> Wire.ofString "Http"
        | Capability.Storage -> Wire.ofString "Storage"
        | Capability.Clipboard -> Wire.ofString "Clipboard"
        | Capability.Navigation -> Wire.ofString "Navigation"

    and encodeSemanticEvent (value: SemanticEvent) : JsonNode =
        Wire.ofObject [ Some("kind", Wire.ofString "Event"); Some("name", Wire.ofString value.Name); value.Key |> Option.map (fun value -> "key", Wire.ofString value); value.Value |> Option.map (fun value -> "value", Wire.ofString value) ]

    and encodeBrowserLocation (value: BrowserLocation) : JsonNode =
        Wire.ofObject [ Some("origin", Wire.ofString value.Origin); Some("path", Wire.ofString value.Path); Some("query", Wire.ofString value.Query); Some("hash", Wire.ofString value.Hash) ]

    and encodeHttpFailureReason (value: HttpFailureReason) : JsonNode =
        match value with
        | HttpFailureReason.Network -> Wire.ofString "network"
        | HttpFailureReason.Aborted -> Wire.ofString "aborted"
        | HttpFailureReason.InvalidResponse -> Wire.ofString "invalid-response"

    and encodeEffectOutcome (value: EffectOutcome) : JsonNode =
        match value with
        | EffectOutcome.Success(f_status, f_body) -> Wire.ofObject [ Some("kind", Wire.ofString "Success"); Some("status", Wire.ofInt f_status); Some("body", Wire.ofJson f_body) ]
        | EffectOutcome.Failure(f_reason, f_status) -> Wire.ofObject [ Some("kind", Wire.ofString "Failure"); Some("reason", encodeHttpFailureReason f_reason); f_status |> Option.map (fun value -> "status", Wire.ofInt value) ]
        | EffectOutcome.Cancelled -> Wire.ofObject [ Some("kind", Wire.ofString "Cancelled") ]
        | EffectOutcome.OutcomeUnknown -> Wire.ofObject [ Some("kind", Wire.ofString "OutcomeUnknown"); Some("reason", Wire.ofString "timeout-after-dispatch") ]

    and encodeStorageFailureReason (value: StorageFailureReason) : JsonNode =
        match value with
        | StorageFailureReason.Unavailable -> Wire.ofString "unavailable"
        | StorageFailureReason.QuotaExceeded -> Wire.ofString "quota-exceeded"

    and encodeStorageOutcome (value: StorageOutcome) : JsonNode =
        match value with
        | StorageOutcome.Success(f_value) -> Wire.ofObject [ Some("kind", Wire.ofString "Success"); Some("value", (Wire.ofNullable Wire.ofString) f_value) ]
        | StorageOutcome.Failure(f_reason) -> Wire.ofObject [ Some("kind", Wire.ofString "Failure"); Some("reason", encodeStorageFailureReason f_reason) ]

    and encodeClipboardFailureReason (value: ClipboardFailureReason) : JsonNode =
        match value with
        | ClipboardFailureReason.Denied -> Wire.ofString "denied"
        | ClipboardFailureReason.Unavailable -> Wire.ofString "unavailable"
        | ClipboardFailureReason.Unknown -> Wire.ofString "unknown"

    and encodeClipboardOutcome (value: ClipboardOutcome) : JsonNode =
        match value with
        | ClipboardOutcome.Success -> Wire.ofObject [ Some("kind", Wire.ofString "Success") ]
        | ClipboardOutcome.Failure(f_reason) -> Wire.ofObject [ Some("kind", Wire.ofString "Failure"); Some("reason", encodeClipboardFailureReason f_reason) ]

    and encodeNavigationFailureReason (value: NavigationFailureReason) : JsonNode =
        match value with
        | NavigationFailureReason.Unavailable -> Wire.ofString "unavailable"
        | NavigationFailureReason.NotSameOrigin -> Wire.ofString "not-same-origin"

    and encodeNavigationOutcome (value: NavigationOutcome) : JsonNode =
        match value with
        | NavigationOutcome.Success(f_location) -> Wire.ofObject [ Some("kind", Wire.ofString "Success"); Some("location", encodeBrowserLocation f_location) ]
        | NavigationOutcome.Dispatched -> Wire.ofObject [ Some("kind", Wire.ofString "Dispatched") ]
        | NavigationOutcome.Failure(f_reason) -> Wire.ofObject [ Some("kind", Wire.ofString "Failure"); Some("reason", encodeNavigationFailureReason f_reason) ]

    and encodeCapabilityId (value: CapabilityId) : JsonNode =
        let (CapabilityId inner) = value
        Wire.ofString inner

    and encodeCapabilityUnsupportedReason (value: CapabilityUnsupportedReason) : JsonNode =
        match value with
        | CapabilityUnsupportedReason.NotNegotiated -> Wire.ofString "not-negotiated"
        | CapabilityUnsupportedReason.VersionUnsupported -> Wire.ofString "version-unsupported"

    and encodeCapabilityRejectedReason (value: CapabilityRejectedReason) : JsonNode =
        match value with
        | CapabilityRejectedReason.MalformedRequest -> Wire.ofString "malformed-request"

    and encodeCapabilityOutcome (value: CapabilityOutcome) : JsonNode =
        match value with
        | CapabilityOutcome.Completed(f_result) -> Wire.ofObject [ Some("kind", Wire.ofString "Completed"); Some("result", Wire.ofJson f_result) ]
        | CapabilityOutcome.Unsupported(f_reason) -> Wire.ofObject [ Some("kind", Wire.ofString "Unsupported"); Some("reason", encodeCapabilityUnsupportedReason f_reason) ]
        | CapabilityOutcome.Rejected(f_reason) -> Wire.ofObject [ Some("kind", Wire.ofString "Rejected"); Some("reason", encodeCapabilityRejectedReason f_reason) ]

    and encodeEffectResult (value: EffectResult) : JsonNode =
        match value with
        | EffectResult.HttpResult(f_correlationId, f_outcome) -> Wire.ofObject [ Some("kind", Wire.ofString "HttpResult"); Some("correlationId", encodeCorrelationId f_correlationId); Some("outcome", encodeEffectOutcome f_outcome) ]
        | EffectResult.StorageResult(f_correlationId, f_outcome) -> Wire.ofObject [ Some("kind", Wire.ofString "StorageResult"); Some("correlationId", encodeCorrelationId f_correlationId); Some("outcome", encodeStorageOutcome f_outcome) ]
        | EffectResult.ClipboardResult(f_correlationId, f_outcome) -> Wire.ofObject [ Some("kind", Wire.ofString "ClipboardResult"); Some("correlationId", encodeCorrelationId f_correlationId); Some("outcome", encodeClipboardOutcome f_outcome) ]
        | EffectResult.NavigationResult(f_correlationId, f_outcome) -> Wire.ofObject [ Some("kind", Wire.ofString "NavigationResult"); Some("correlationId", encodeCorrelationId f_correlationId); Some("outcome", encodeNavigationOutcome f_outcome) ]
        | EffectResult.CapabilityResult(f_correlationId, f_capability, f_version, f_outcome) -> Wire.ofObject [ Some("kind", Wire.ofString "CapabilityResult"); Some("correlationId", encodeCorrelationId f_correlationId); Some("capability", encodeCapabilityId f_capability); Some("version", Wire.ofInt f_version); Some("outcome", encodeCapabilityOutcome f_outcome) ]

    and encodeProtocolRevision (value: ProtocolRevision) : JsonNode =
        Wire.ofObject [ Some("major", Wire.ofInt value.Major); Some("minor", Wire.ofInt value.Minor) ]

    and encodeContractIdentity (value: ContractIdentity) : JsonNode =
        Wire.ofObject [ Some("unit", Wire.ofString value.Unit); Some("version", Wire.ofInt value.Version); Some("fingerprint", Wire.ofString value.Fingerprint) ]

    and encodeCapabilityOffer (value: CapabilityOffer) : JsonNode =
        Wire.ofObject [ Some("id", encodeCapabilityId value.Id); Some("version", Wire.ofInt value.Version); Some("fingerprint", Wire.ofString value.Fingerprint) ]

    and encodeHostHandshake (value: HostHandshake) : JsonNode =
        Wire.ofObject [ Some("protocol", encodeProtocolRevision value.Protocol); Some("contract", encodeContractIdentity value.Contract); Some("capabilities", (Wire.ofList encodeCapabilityOffer) value.Capabilities) ]

    and encodeHandshakeRejection (value: HandshakeRejection) : JsonNode =
        match value with
        | HandshakeRejection.ProtocolUnsupported(f_offered) -> Wire.ofObject [ Some("kind", Wire.ofString "ProtocolUnsupported"); Some("offered", encodeProtocolRevision f_offered) ]
        | HandshakeRejection.ContractMismatch(f_expected, f_offered) -> Wire.ofObject [ Some("kind", Wire.ofString "ContractMismatch"); Some("expected", encodeContractIdentity f_expected); Some("offered", encodeContractIdentity f_offered) ]
        | HandshakeRejection.CapabilityUnavailable(f_id, f_version) -> Wire.ofObject [ Some("kind", Wire.ofString "CapabilityUnavailable"); Some("id", encodeCapabilityId f_id); Some("version", Wire.ofInt f_version) ]
        | HandshakeRejection.HandshakeMissing -> Wire.ofObject [ Some("kind", Wire.ofString "HandshakeMissing") ]

    and encodeEngineHandshake (value: EngineHandshake) : JsonNode =
        match value with
        | EngineHandshake.Accepted(f_protocol, f_contract, f_capabilities) -> Wire.ofObject [ Some("kind", Wire.ofString "Accepted"); Some("protocol", encodeProtocolRevision f_protocol); Some("contract", encodeContractIdentity f_contract); Some("capabilities", (Wire.ofList encodeCapabilityOffer) f_capabilities) ]
        | EngineHandshake.Rejected(f_reason) -> Wire.ofObject [ Some("kind", Wire.ofString "Rejected"); Some("reason", encodeHandshakeRejection f_reason) ]

    and encodeBrowserToEngineMessage (value: BrowserToEngineMessage) : JsonNode =
        match value with
        | BrowserToEngineMessage.Initialize(f_capabilities, f_location, f_handshake) -> Wire.ofObject [ Some("kind", Wire.ofString "Initialize"); Some("protocolVersion", Wire.ofInt 1L); Some("capabilities", (Wire.ofList encodeCapability) f_capabilities); Some("location", encodeBrowserLocation f_location); f_handshake |> Option.map (fun value -> "handshake", encodeHostHandshake value) ]
        | BrowserToEngineMessage.Event(f_event) -> Wire.ofObject [ Some("kind", Wire.ofString "Event"); Some("event", encodeSemanticEvent f_event) ]
        | BrowserToEngineMessage.EffectResult(f_result) -> Wire.ofObject [ Some("kind", Wire.ofString "EffectResult"); Some("result", encodeEffectResult f_result) ]
        | BrowserToEngineMessage.LocationChanged(f_location) -> Wire.ofObject [ Some("kind", Wire.ofString "LocationChanged"); Some("location", encodeBrowserLocation f_location) ]
        | BrowserToEngineMessage.CapabilityFact(f_capability, f_version, f_fact) -> Wire.ofObject [ Some("kind", Wire.ofString "CapabilityFact"); Some("capability", encodeCapabilityId f_capability); Some("version", Wire.ofInt f_version); Some("fact", Wire.ofJson f_fact) ]

    and encodeViewPrimitive (value: ViewPrimitive) : JsonNode =
        match value with
        | ViewPrimitive.Text inner -> Wire.ofString inner
        | ViewPrimitive.Number inner -> Wire.ofNumber inner
        | ViewPrimitive.Flag inner -> Wire.ofBool inner

    and encodeViewItem (value: Map<string, ViewPrimitive>) : JsonNode =
        Wire.ofMap encodeViewPrimitive value

    and encodeViewValue (value: ViewValue) : JsonNode =
        match value with
        | ViewValue.Text inner -> Wire.ofString inner
        | ViewValue.Number inner -> Wire.ofNumber inner
        | ViewValue.Flag inner -> Wire.ofBool inner
        | ViewValue.Items inner -> (Wire.ofList encodeViewItem) inner

    and encodeViewState (value: Map<string, ViewValue>) : JsonNode =
        Wire.ofMap encodeViewValue value

    and encodeHttpMethod (value: HttpMethod) : JsonNode =
        match value with
        | HttpMethod.Get -> Wire.ofString "GET"
        | HttpMethod.Put -> Wire.ofString "PUT"
        | HttpMethod.Post -> Wire.ofString "POST"
        | HttpMethod.Patch -> Wire.ofString "PATCH"
        | HttpMethod.Delete -> Wire.ofString "DELETE"

    and encodeHttpEffectRequest (value: HttpEffectRequest) : JsonNode =
        Wire.ofObject [ Some("kind", Wire.ofString "Http"); Some("correlationId", encodeCorrelationId value.CorrelationId); Some("method", encodeHttpMethod value.Method); Some("url", Wire.ofString value.Url); value.Headers |> Option.map (fun value -> "headers", (Wire.ofMap Wire.ofString) value); value.Body |> Option.map (fun value -> "body", Wire.ofString value); Some("timeoutMs", Wire.ofInt value.TimeoutMs) ]

    and encodeStorageEffectRequest (value: StorageEffectRequest) : JsonNode =
        match value with
        | StorageEffectRequest.Get(f_correlationId, f_key) -> Wire.ofObject [ Some("kind", Wire.ofString "Storage"); Some("operation", Wire.ofString "get"); Some("correlationId", encodeCorrelationId f_correlationId); Some("key", Wire.ofString f_key) ]
        | StorageEffectRequest.Set(f_correlationId, f_key, f_value) -> Wire.ofObject [ Some("kind", Wire.ofString "Storage"); Some("operation", Wire.ofString "set"); Some("correlationId", encodeCorrelationId f_correlationId); Some("key", Wire.ofString f_key); Some("value", Wire.ofString f_value) ]
        | StorageEffectRequest.Remove(f_correlationId, f_key) -> Wire.ofObject [ Some("kind", Wire.ofString "Storage"); Some("operation", Wire.ofString "remove"); Some("correlationId", encodeCorrelationId f_correlationId); Some("key", Wire.ofString f_key) ]

    and encodeClipboardEffectRequest (value: ClipboardEffectRequest) : JsonNode =
        Wire.ofObject [ Some("kind", Wire.ofString "Clipboard"); Some("correlationId", encodeCorrelationId value.CorrelationId); Some("operation", Wire.ofString "writeText"); Some("text", Wire.ofString value.Text) ]

    and encodeNavigationEffectRequest (value: NavigationEffectRequest) : JsonNode =
        match value with
        | NavigationEffectRequest.Push(f_correlationId, f_url) -> Wire.ofObject [ Some("kind", Wire.ofString "Navigation"); Some("operation", Wire.ofString "push"); Some("correlationId", encodeCorrelationId f_correlationId); Some("url", Wire.ofString f_url) ]
        | NavigationEffectRequest.Replace(f_correlationId, f_url) -> Wire.ofObject [ Some("kind", Wire.ofString "Navigation"); Some("operation", Wire.ofString "replace"); Some("correlationId", encodeCorrelationId f_correlationId); Some("url", Wire.ofString f_url) ]
        | NavigationEffectRequest.Back(f_correlationId) -> Wire.ofObject [ Some("kind", Wire.ofString "Navigation"); Some("operation", Wire.ofString "back"); Some("correlationId", encodeCorrelationId f_correlationId) ]
        | NavigationEffectRequest.Forward(f_correlationId) -> Wire.ofObject [ Some("kind", Wire.ofString "Navigation"); Some("operation", Wire.ofString "forward"); Some("correlationId", encodeCorrelationId f_correlationId) ]

    and encodeCapabilityEffectRequest (value: CapabilityEffectRequest) : JsonNode =
        Wire.ofObject [ Some("kind", Wire.ofString "Capability"); Some("correlationId", encodeCorrelationId value.CorrelationId); Some("capability", encodeCapabilityId value.Capability); Some("version", Wire.ofInt value.Version); Some("request", Wire.ofJson value.Request) ]

    and encodeEffectRequest (value: EffectRequest) : JsonNode =
        match value with
        | EffectRequest.Http inner -> encodeHttpEffectRequest inner
        | EffectRequest.Storage inner -> encodeStorageEffectRequest inner
        | EffectRequest.Clipboard inner -> encodeClipboardEffectRequest inner
        | EffectRequest.Navigation inner -> encodeNavigationEffectRequest inner
        | EffectRequest.Capability inner -> encodeCapabilityEffectRequest inner

    and encodeEngineToBrowserMessage (value: EngineToBrowserMessage) : JsonNode =
        Wire.ofObject [ Some("view", encodeViewState value.View); Some("effects", (Wire.ofList encodeEffectRequest) value.Effects); Some("cancellations", (Wire.ofList encodeCorrelationId) value.Cancellations); value.Handshake |> Option.map (fun value -> "handshake", encodeEngineHandshake value) ]

    let parseCorrelationId (json: string) = Wire.parse decodeCorrelationId json
    let serializeCorrelationId (value: CorrelationId) = (encodeCorrelationId value).ToJsonString()
    let parseCapability (json: string) = Wire.parse decodeCapability json
    let serializeCapability (value: Capability) = (encodeCapability value).ToJsonString()
    let parseSemanticEvent (json: string) = Wire.parse decodeSemanticEvent json
    let serializeSemanticEvent (value: SemanticEvent) = (encodeSemanticEvent value).ToJsonString()
    let parseBrowserLocation (json: string) = Wire.parse decodeBrowserLocation json
    let serializeBrowserLocation (value: BrowserLocation) = (encodeBrowserLocation value).ToJsonString()
    let parseHttpFailureReason (json: string) = Wire.parse decodeHttpFailureReason json
    let serializeHttpFailureReason (value: HttpFailureReason) = (encodeHttpFailureReason value).ToJsonString()
    let parseEffectOutcome (json: string) = Wire.parse decodeEffectOutcome json
    let serializeEffectOutcome (value: EffectOutcome) = (encodeEffectOutcome value).ToJsonString()
    let parseStorageFailureReason (json: string) = Wire.parse decodeStorageFailureReason json
    let serializeStorageFailureReason (value: StorageFailureReason) = (encodeStorageFailureReason value).ToJsonString()
    let parseStorageOutcome (json: string) = Wire.parse decodeStorageOutcome json
    let serializeStorageOutcome (value: StorageOutcome) = (encodeStorageOutcome value).ToJsonString()
    let parseClipboardFailureReason (json: string) = Wire.parse decodeClipboardFailureReason json
